#!/usr/bin/env bash
wait_active(){ local u="$1" t="${2:-30}" i; for ((i=0;i<t;i++)); do systemctl is-active --quiet "$u"&&return 0; sleep 1; done; systemctl status "$u" --no-pager||true; return 1; }
installation_health_gate(){ log "running post-install health gate"; wait_active cockpit-ups-wol-agent.service 30||die "agent failed startup health gate"; systemctl is-enabled --quiet cockpit-ups-wol-agent.service||die "agent is not enabled"; systemctl is-enabled --quiet cockpit-ups-wol-health.timer||die "health timer is not enabled"; wait_active cockpit-ups-wol-health.timer 15||die "health timer inactive"; if unit_exists cockpit.socket; then systemctl is-enabled --quiet cockpit.socket||die "cockpit.socket not enabled"; fi; if [[ "$PROFILE" == local-server ]]&&command -v upsc>/dev/null; then local end=$((SECONDS+30)); while ((SECONDS<end)); do upsc ups@localhost>/dev/null 2>&1&&break; sleep 2; done; upsc ups@localhost>/dev/null 2>&1||die "NUT health check failed"; fi; log "starting 60-second probation"; local end=$((SECONDS+60)); while ((SECONDS<end)); do systemctl is-active --quiet cockpit-ups-wol-agent.service||die "agent failed during probation"; sleep 5; done; log "post-install probation passed"; }
